int bluetooth_getsockopt(struct socket *sock, int level, int optname, char __user *optval, int __user *optlen)
{
    int ret = 0;
    struct sock *sk = sock->sk;
    int len;

    if (sk == NULL)
        return -EINVAL;

    if (level != SOL_BLUETOOTH)
        return -EINVAL;

    switch (optname) {
    case BT_SECURITY:
    case BT_SECURITY_REMOTE:
        len = min(4, (int)__get_user(*optlen, optlen) ? : 0);
        if (len < 0)
            return len;

        if (len >= 4)
            ret = __put_user(bt_sk(sk)->security, (u8 __user *)optval);
        break;

    case BT_DEFER_SETUP:
        len = min(4, (int)__get_user(*optlen, optlen) ? : 0);
        if (len < 0)
            return len;

        if (len >= 4)
            ret = __put_user(bt_sk(sk)->defer_setup, (u8 __user *)optval);
        break;

    default:
        ret = -ENOPROTOOPT;
        break;
    }

    return ret;
}

int bluetooth_getsockopt(struct socket *sock, int level, int optname, char __user *optval, int __user *optlen)
{
    if (!sock || !optval || !optlen)
        return -EINVAL;

    if (level != SOL_BLUETOOTH)
        return -ENOPROTOOPT;

    switch (optname) {
    case BT_SECURITY:
    {
        int sec_level = sock->sk->security;
        int len = 0;

        if (get_user(len, optlen))
            return -EFAULT;

        if (len < 0)
            return -EINVAL;

        if (put_user(sec_level, optval))
            return -EFAULT;
        if (put_user(sizeof(sec_level), optlen))
            return -EFAULT;
        return 0;
    }
    case BT_DEFER_SETUP:
    {
        int defer = sock->sk->defer_setup;
        int len = 0;

        if (get_user(len, optlen))
            return -EFAULT;

        if (len < 0)
            return -EINVAL;

        if (put_user(defer, optval))
            return -EFAULT;
        if (put_user(sizeof(defer), optlen))
            return -EFAULT;
        return 0;
    }
    default:
        return -ENOPROTOOPT;
    }
}

int bluetooth_getsockopt(struct socket *sock, int level, int optname, char __user *optval, int __user *optlen)
{
    int ret = 0;
    struct sock *sk = sock->sk;
    int len;

    if (!sk)
        return -EINVAL;

    if (level != SOL_BLUETOOTH)
        return -ENOPROTOOPT;

    switch (optname) {
    case BT_SECURITY:
        len = 1;
        if (put_user(len, optlen))
            return -EFAULT;

        if (copy_to_user(optval, &sk->security, len))
            return -EFAULT;
        break;

    case BT_DEFER_SETUP:
        len = sizeof(int);
        if (put_user(len, optlen))
            return -EFAULT;

        if (copy_to_user(optval, &sk->defer_setup, len))
            return -EFAULT;
        break;

    default:
        return -ENOPROTOOPT;
    }

    return ret;
}

int bluetooth_getsockopt(struct socket *sock, int level, int optname, char __user *optval, int __user *optlen)
{
    int ret = 0;
    struct sock *sk = sock->sk;

    if (!sk || !sock)
        return -EINVAL;

    if (level != SOL_RFCOMM) {
        return -ENOPROTOOPT;
    }

    switch (optname) {
        case RFCOMM_SECURITY: {
            int sec = sk->sec_level;
            if (put_user(sec, (int __user *)optval) || put_user(sizeof(int), optlen))
                ret = -EFAULT;
            break;
        }
        case RFCOMM_DEFER_SETUP: {
            int defer = sk->defer_setup;
            if (put_user(defer, (int __user *)optval) || put_user(sizeof(int), optlen))
                ret = -EFAULT;
            break;
        }
        default:
            ret = -ENOPROTOOPT;
            break;
    }

    return ret;
}
